-- OBADIAH c1-v1 - KOR
-- 환상이라 오바랄의 이와–같이 말씀하셨다 주 여호와께서 에돔에–관하여 소식을 들었도다 –로부터 여호와 그리고–사자가 열방들–가운데 보내졌다 일어나라 그리고–일어나자 그녀를–대항하여 –전투를–위하여

